"""Snap span edges to a fixed step and label the result."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span


def check_step(step: int) -> None:
    """Reject steps that do not divide an hour."""
    if step <= 0 or 60 % step:
        raise ValueError(f"bad rounding step: {step}")


def round_minutes(value: int, step: int) -> int:
    """Nearest multiple of step, with halves going up."""
    return (value + step // 2) // step * step


def round_span(span: Span, step: int) -> Span:
    """Snap both edges; a collapsed span is an error."""
    return Span(
        round_minutes(span.start, step),
        round_minutes(span.end, step)
    )


def format_duration(minutes: int) -> str:
    hours, rest = divmod(minutes, 60)
    return f"{hours}h {rest}m"


def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    length = format_duration(span.minutes)
    return f"{format_span(span)} ({length})"


def round_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """One label per span, rounded to the step."""
    check_step(step)
    return [
        span_label(round_span(span, step)) for span in spans
    ]

