# owner: platform
import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_spans


class RoundingTests(unittest.TestCase):
    def test_label_format(self):
        span = parse_span("09:00-17:15")
        self.assertEqual(
            round_spans([span], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_edges_snap_to_nearest(self):
        span = parse_span("08:53-17:08")
        self.assertEqual(
            round_spans([span], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        span = Span(7 * 60 + 15, 9 * 60 + 45)
        self.assertEqual(
            round_spans([span], 30),
            ["07:30-10:00 (2h 30m)"]
        )

    def test_one_label_per_span_in_order(self):
        spans = [Span(600, 660), Span(60, 120)]
        self.assertEqual(
            round_spans(spans, 60),
            ["10:00-11:00 (1h 0m)", "01:00-02:00 (1h 0m)"]
        )

    def test_end_of_day_stays_valid(self):
        span = parse_span("23:00-24:00")
        self.assertEqual(
            round_spans([span], 20),
            ["23:00-24:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(0, 60)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(61, 64)], 15)
